const caseId = String($('Petition Query Webhook').first().json.query?.caseId || '').trim();
function getString(prop) {
  if (!prop) return '';
  if (prop.type === 'title') return (prop.title || []).map(t => t.plain_text || '').join('');
  if (prop.type === 'rich_text') return (prop.rich_text || []).map(t => t.plain_text || '').join('');
  if (prop.type === 'select') return prop.select?.name || '';
  if (prop.type === 'multi_select') return (prop.multi_select || []).map(t => t.name || '').filter(Boolean).join('、');
  if (prop.type === 'checkbox') return prop.checkbox === true ? 'true' : 'false';
  if (prop.type === 'date') return prop.date?.start || '';
  if (prop.type === 'created_time') return prop.created_time || '';
  if (prop.type === 'last_edited_time') return prop.last_edited_time || '';
  if (prop.type === 'phone_number') return prop.phone_number || '';
  return '';
}
function getImages(prop) {
  if (!prop || prop.type !== 'files') return [];
  return (prop.files || []).map(f => f.file?.url || f.external?.url || '').filter(Boolean);
}
const page = $input.all().map(item => item.json).find(item => getString(item.properties?.['請託案號']) === caseId);
if (!page) return [{ json: { found: false } }];
const props = page.properties || {};
const summary = getString(props['公開摘要']);
const content = getString(props['託辦事項']);
return [{ json: {
  found: true,
  caseId: getString(props['請託案號']),
  title: summary || content,
  caseType: getString(props['託辦類別']),
  caseArea: getString(props['案件區域']),
  status: getString(props['處理狀況']),
  summary,
  reply: getString(props['回覆內容']),
  beforeImages: getImages(props['改善前圖片']),
  afterImages: getImages(props['改善後圖片']),
  date: (getString(props['請託日期']) || getString(props['建立時間'])).slice(0, 10),
  lastUpdate: getString(props['上次編輯時間']).slice(0, 10)
} }];
